    #[inductive(append_flip_bit)]
    fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
        let cur_idx = pre.combiner[node_id].get_Appending_cur_idx();
        let tail_val = pre.combiner[node_id].get_Appending_tail();
        let phys_idx = log_entry_idx(cur_idx as int, pre.buffer_size);

        // Key lemma: within [tail - buffer_size, tail), all physical indices are distinct.
        // cur_idx is in this window (from combiner_valid: tail - buffer_size <= cur_idx < tail).
        log_entry_idx_wrap_around(
            (pre.tail - pre.buffer_size) as nat,
            pre.buffer_size,
            cur_idx,
        );
        // => forall i, (tail - buffer_size) <= i < tail && i != cur_idx
        //    => log_entry_idx(i, buffer_size) != phys_idx

        // phys_idx of cur_idx + buffer_size equals phys_idx (wrap-around)
        phys_idx_add_buffer(cur_idx as int, pre.buffer_size);
        // For uniqueness within [tail, tail + buffer_size):
        log_entry_idx_wrap_around(
            pre.tail,
            pre.buffer_size,
            (cur_idx + pre.buffer_size as int) as nat,
        );

        let min_lv_pre = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
        map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
        let min_lv_post = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
        map_min_value_smallest(post.local_versions, (post.num_replicas - 1) as nat);

        // ---- ranges_no_overlap ----
        assert forall |i: NodeId, j: NodeId|
            post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
            implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
            if i == node_id {
                // post.combiner[i] = Appending { cur_idx + 1, tail_val }
                // post.combiner[j] = pre.combiner[j]
                assert(pre.combiner[node_id].no_overlap_with(pre.combiner[j]));
                // For Appending vs Appending: (cur_idx >= tail2) || (tail <= cur_idx2)
                //   => (cur_idx+1 >= tail2) || (tail <= cur_idx2)  [strictly stronger in first case]
                // For Appending vs Guard { cur }: (cur_idx > cur) || (tail <= cur)
                //   => (cur_idx+1 > cur) || (tail <= cur)
                // For Appending vs others: no_overlap_with returns true
            } else if j == node_id {
                assert(pre.combiner[i].no_overlap_with(pre.combiner[node_id]));
            } else {
                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
            }
        };

        // ---- upcoming_bits_are_not_alive ----
        // post.tail = pre.tail, post.local_versions = pre.local_versions
        // min_lv_post = min_lv_pre
        assert forall |i: int| post.tail <= i < min_lv_post + post.buffer_size
            implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
            let i_phys = log_entry_idx(i, post.buffer_size);
            if i_phys == phys_idx {
                // i shares physical index with cur_idx.
                // i >= tail > cur_idx, and i < min_lv_post + buffer_size <= tail + buffer_size
                // cur_idx + buffer_size is in [tail, tail + buffer_size) and has phys_idx
                // By log_entry_idx_wrap_around(tail, ..., cur_idx + buffer_size):
                //   any j in [tail, tail+buffer_size) with j != cur_idx+buffer_size has different phys_idx
                // So i == cur_idx + buffer_size
                assert(i == cur_idx + pre.buffer_size as int) by {
                    let cib = cur_idx + pre.buffer_size as int;
                    assert(pre.tail <= cib);
                    assert(cib < pre.tail + pre.buffer_size as int);
                    assert(pre.tail <= i);
                    assert(i < pre.tail + pre.buffer_size as int);
                };
                // post.alive_bits[phys_idx] = log_entry_alive_value(cur_idx, buffer_size)
                // log_entry_alive_value(cur_idx + buffer_size, buffer_size)
                //   != log_entry_alive_value(cur_idx, buffer_size)
                log_entry_alive_value_wrap_around(cur_idx as int, post.buffer_size);
            } else {
                // Alive bit for i is unchanged
                assert(post.alive_bits[i_phys] == pre.alive_bits[i_phys]);
                // i >= post.tail = pre.tail => not alive in pre
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            }
        };

        // ---- inv_buffer_contents ----
        assert forall |i: int| pre.tail - pre.buffer_size <= i < pre.tail
            implies (
                (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                    i < min_lv_post)
                ==
                #[trigger] post.contents.contains_key(i)
            ) by {
            if i == cur_idx as int {
                // Alive bit now set to alive, contents now contains cur_idx
                // Need: (true || ...) == true  =>  true == true ✓
                // In pre: cur_idx >= min_lv_pre (because min_lv_pre <= local_versions[node_id] <= cur_idx)
                assert(min_lv_pre <= cur_idx as int);
                // Also in pre: !log_entry_is_alive(pre.alive_bits, cur_idx, ...)
                //   (from combiner_valid: forall cur_idx <= i < tail => !alive)
                // And !pre.contents.contains_key(cur_idx) (by iff in pre inv_buffer_contents: false || false == false)
            } else {
                // i != cur_idx, both in [tail - buffer_size, tail)
                // => log_entry_idx(i, buffer_size) != phys_idx
                assert(log_entry_idx(i, pre.buffer_size) != phys_idx);
                // => alive bit for i unchanged
                assert(post.alive_bits[log_entry_idx(i, post.buffer_size)]
                    == pre.alive_bits[log_entry_idx(i, post.buffer_size)]);
                // => contents for i unchanged (we only deposited cur_idx)
                assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
            }
        };
        assert forall |i: int| pre.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
            // We only deposited cur_idx < pre.tail, so no new entries at i >= tail
            assert(!pre.contents.contains_key(i));
        };

        // ---- all_combiner_valid ----
        // For node_id: new state is Appending { cur_idx + 1, tail_val }
        // Need: forall i, cur_idx + 1 <= i < tail_val => !log_entry_is_alive(post.alive_bits, i, buffer_size)
        assert forall |i: nat| (cur_idx + 1) <= i < tail_val
            implies !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
            // In pre: !log_entry_is_alive(pre.alive_bits, i, buffer_size)  (i in [cur_idx, tail))
            assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
            // i in [tail - buffer_size, tail) and i != cur_idx => log_entry_idx(i) != phys_idx
            assert(i as int != cur_idx as int);
            assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
            // => alive bit unchanged
        };

        // ---- all_reader_state_valid ----
        assert forall |reader_id: NodeId| #![trigger post.combiner[reader_id]]
            post.combiner.contains_key(reader_id) && post.combiner[reader_id].is_Reading()
            implies post.reader_state_valid(reader_id, post.combiner[reader_id].get_Reading_0()) by {

            // post.combiner[reader_id] = pre.combiner[reader_id] (unchanged, reader_id != node_id)
            // because node_id's combiner is Appending, not Reading
            let rs = post.combiner[reader_id].get_Reading_0();
            assert(pre.reader_state_valid(reader_id, rs));

            // For entries in the reader's traversed range [start, cur] ⊆ [local_version, tail)
            // ⊆ [tail - buffer_size, tail):  alive bits are unchanged (distinct phys_idx from cur_idx)
            // Contents are only extended (deposit only adds), so contents.contains_key is preserved.
            match rs {
                ReaderState::Starting { .. } => {}
                ReaderState::Range { start, end, cur } => {
                    assert forall |i: nat| start <= i < cur
                        implies log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                        // i in [start, cur) ⊆ [tail - buffer_size, tail), i != cur_idx
                        // (cur_idx not alive in pre; but entries in [start,cur) are alive in pre => cur_idx not among them)
                        assert(log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                        // i != cur_idx (cur_idx is not alive in pre, but i is alive in pre)
                        assert(i as int != cur_idx as int);
                        assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
