        (pre.tail as int) - (pre.buffer_size as int) <= i < pre.tail as int && i != cur_idx as int
        implies log_entry_idx(i, pre.buffer_size) != phys_idx by {
        // Both i and cur_idx are in the window [tail-buffer_size, tail) of size buffer_size
        // |i - cur_idx| < buffer_size and != 0 => different physical indices
        if i > cur_idx as int {
            assert(0 < i - cur_idx as int);
            assert(i - cur_idx as int < pre.buffer_size as int);
            log_entry_idx_neq_in_window(i, cur_idx as int, pre.buffer_size);
        } else {
            assert(0 < cur_idx as int - i);
            assert(cur_idx as int - i < pre.buffer_size as int);
            log_entry_idx_neq_in_window(i, cur_idx as int, pre.buffer_size);
        }
    };

    // ---- ranges_no_overlap ----
    assert forall |i: NodeId, j: NodeId|
        post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
        implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
        if i == node_id {
            assert(pre.combiner[node_id].no_overlap_with(pre.combiner[j]));
        } else if j == node_id {
            assert(pre.combiner[i].no_overlap_with(pre.combiner[node_id]));
        } else {
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    // ---- upcoming_bits_are_not_alive ----
    assert forall |i: int| post.tail <= i < min_lv_post + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        let i_phys = log_entry_idx(i, post.buffer_size);
        if i_phys == phys_idx {
            // i >= tail > cur_idx, i < tail + buffer_size, and phys_idx(i) == phys_idx(cur_idx)
            // The only i in [tail, tail+buffer_size) with phys_idx == phys_idx(cur_idx) is cur_idx + buffer_size
            let cib = cur_idx + pre.buffer_size as int;
            // cib is in [tail, tail+buffer_size) since tail - buffer_size <= cur_idx < tail
            assert(pre.tail as int <= cib);
            assert(cib < pre.tail as int + pre.buffer_size as int);
            // i is also in [tail, tail+buffer_size)
            assert(pre.tail as int <= i);
            assert(i < pre.tail as int + pre.buffer_size as int);
            // log_entry_idx(cib) == phys_idx (from phys_idx_add_buffer)
            // So log_entry_idx(i) == log_entry_idx(cib).
            // If i != cib, they differ in (0, buffer_size) => different phys_idx. Contradiction.
            assert(i == cib) by {
                if i > cib {
                    assert(0 < i - cib && i - cib < pre.buffer_size as int);
                    log_entry_idx_neq_in_window(i, cib, pre.buffer_size);
                    assert(false);
                } else if cib > i {
                    assert(0 < cib - i && cib - i < pre.buffer_size as int);
                    log_entry_idx_neq_in_window(i, cib, pre.buffer_size);
                    assert(false);
                }
            };
            // Now i == cur_idx + buffer_size
            // post.alive_bits[phys_idx] = log_entry_alive_value(cur_idx, buffer_size)
            // log_entry_alive_value(i = cur_idx + buffer_size, buffer_size) != above
            log_entry_alive_value_wrap_around(cur_idx as int, post.buffer_size);
        } else {
            // Alive bit for i unchanged (different physical slot)
            assert(post.alive_bits[i_phys] == pre.alive_bits[i_phys]);
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
        }
    };

    // ---- inv_buffer_contents ----
    assert forall |i: int| pre.tail - pre.buffer_size <= i < pre.tail
        implies (
            (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                i < min_lv_post)
            ==
            #[trigger] post.contents.contains_key(i)
        ) by {
        if i == cur_idx as int {
            // After transition: alive bit is now set, and contents has cur_idx
            // min_lv_pre <= local_versions[node_id] <= cur_idx => cur_idx >= min_lv_pre
            assert(min_lv_pre as int <= cur_idx as int);
            // pre: !alive and cur_idx >= min_lv => !contents.contains_key(cur_idx)
            // post: alive=true, contents.contains_key(cur_idx)=true. Both sides true. ✓
        } else {
            // i != cur_idx, i in [tail-buffer_size, tail), so different physical index
            assert(log_entry_idx(i, pre.buffer_size) != phys_idx);
            // Alive bit for i unchanged
            assert(post.alive_bits[log_entry_idx(i, post.buffer_size)]
                == pre.alive_bits[log_entry_idx(i, post.buffer_size)]);
            // Contents for i unchanged (deposit was at cur_idx only)
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
        }
    };
    assert forall |i: int| pre.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
        // Deposit was at cur_idx < pre.tail; no new entries at i >= tail
        assert(!pre.contents.contains_key(i));
    };

    // ---- all_combiner_valid ----
    // For node_id: new combiner is Appending { cur_idx + 1, tail_val }
    // Need: local_versions[node_id] <= cur_idx + 1 <= tail_val
    //   and (tail as int) - buffer_size <= cur_idx + 1 <= tail
    //   and forall i, cur_idx + 1 <= i < tail_val => !alive(i)
    assert forall |i: nat| (cur_idx + 1) <= i < tail_val
        implies !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
        // In pre, !alive for i in [cur_idx, tail) (from combiner_valid)
        assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
        // i != cur_idx (i > cur_idx), and i in [tail-buffer_size, tail), so different phys_idx
        assert(i as int != cur_idx as int);
        assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
        // Alive bit for i unchanged
    };

    // ---- all_reader_state_valid ----
    assert forall |reader_id: NodeId| #![trigger post.combiner[reader_id]]
        post.combiner.contains_key(reader_id) && post.combiner[reader_id].is_Reading()
        implies post.reader_state_valid(reader_id, post.combiner[reader_id].get_Reading_0()) by {
        let rs = post.combiner[reader_id].get_Reading_0();
        assert(pre.reader_state_valid(reader_id, rs));
        match rs {
            ReaderState::Starting { .. } => {}
            ReaderState::Range { start, end, cur } => {
                assert forall |i: nat| start <= i < cur
                    implies log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    // i is alive in pre
                    assert(log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                    // cur_idx is NOT alive in pre (from combiner_valid)
                    // Therefore cur_idx != i (since i is alive)
                    assert(i as int != cur_idx as int);
                    // i in [tail - buffer_size, tail) (from pointer_differences + reader state)
                    // so different phys_idx from cur_idx
                    assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
                };
            }
            ReaderState::Guard { start, end, cur, val } => {
                assert forall |i: nat| start <= i <= cur
                    implies log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                    assert(i as int != cur_idx as int);
                    assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
                };
                // post.contents[cur] == val since cur != cur_idx (cur is alive, cur_idx is not)
                assert(cur as int != cur_idx as int);
                assert(post.contents[cur as int] === val);
            }
        }
    };
}

