// ---- all_combiner_valid ----
assert forall |nid: NodeId| #[trigger] post.combiner.contains_key(nid)
    implies post.combiner_valid(nid, post.combiner[nid]) by {
    if nid == node_id {
        // New combiner: Appending { cur_idx + 1, tail_val }
        // Prove alive bits condition: forall i, cur_idx+1 <= i < tail_val => !alive
        assert forall |i: nat| (cur_idx + 1) <= i < tail_val
            implies !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
            assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
            assert(i as int != cur_idx as int);
            assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
        };
    } else {
        // Other nodes: combiner unchanged from pre
        assert(pre.combiner_valid(nid, pre.combiner[nid]));
        // Only the alive bits condition for Appending states is potentially affected
        match pre.combiner[nid] {
            CombinerState::Appending { cur_idx: cur_idx2, tail: tail2 } => {
                // pre.no_overlap_with says (cur_idx >= tail2) || (tail_val <= cur_idx2)
                assert(pre.combiner[node_id].no_overlap_with(pre.combiner[nid]));
                assert forall |i: nat| cur_idx2 <= i < tail2
                    implies !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                    // i != cur_idx from no_overlap:
                    // Case (cur_idx >= tail2): i < tail2 <= cur_idx
                    // Case (tail_val <= cur_idx2): cur_idx < tail_val <= cur_idx2 <= i
                    assert(i as int != cur_idx as int);
                    // i and cur_idx both in [tail-buffer_size, tail) (as int), so different phys_idx
                    assert(log_entry_idx(i as int, pre.buffer_size) != phys_idx);
                };
            }
            _ => {}
        }
    }
};

